const mongoose = require("mongoose");
const fs = require("fs");
const path = require("path");

const AbsoluteData = require("../models/AbsoluteData");

// ------------------------------------------------------------
// CONFIGURATION
// ------------------------------------------------------------

const MONGO_URI = "mongodb://localhost:27017/numbergrid";

// The dry-run report generated by the 100-PDF test.
const REPORT_PATH = path.resolve(
  __dirname,
  "../reports/absolute-v2-100-pdf-dry-run.json",
);

// Comparison report output.
const OUTPUT_PATH = path.resolve(
  __dirname,
  "../../absolute-v2-100-pdf-comparison.json",
);

// Expected number of PDFs in this test.
const EXPECTED_FILES = 100;

// ------------------------------------------------------------
// HELPERS
// ------------------------------------------------------------

function normalizeDate(value) {
  return String(value || "").trim();
}

function getNumbers(group) {
  return (group?.numbers || [])
    .map((item) =>
      String(typeof item === "string" ? item : item?.number || "").trim(),
    )
    .filter(Boolean)
    .sort();
}

function groupByPrize(series = []) {
  const result = new Map();

  for (const group of series) {
    const prize = Number(group.prize);

    if (!Number.isFinite(prize)) {
      continue;
    }

    if (!result.has(prize)) {
      result.set(prize, []);
    }

    result.get(prize).push(...getNumbers(group));
  }

  for (const [prize, numbers] of result) {
    result.set(prize, numbers.sort());
  }

  return result;
}

function findDifferences(expected, actual) {
  const expectedCounts = new Map();
  const actualCounts = new Map();

  for (const number of expected) {
    expectedCounts.set(number, (expectedCounts.get(number) || 0) + 1);
  }

  for (const number of actual) {
    actualCounts.set(number, (actualCounts.get(number) || 0) + 1);
  }

  const missing = [];
  const extra = [];

  for (const [number, count] of expectedCounts) {
    const actualCount = actualCounts.get(number) || 0;

    for (let i = actualCount; i < count; i++) {
      missing.push(number);
    }
  }

  for (const [number, count] of actualCounts) {
    const expectedCount = expectedCounts.get(number) || 0;

    for (let i = expectedCount; i < count; i++) {
      extra.push(number);
    }
  }

  return { missing, extra };
}

// ------------------------------------------------------------
// MAIN COMPARISON
// ------------------------------------------------------------

async function main() {
  if (!fs.existsSync(REPORT_PATH)) {
    throw new Error(`Dry-run report not found: ${REPORT_PATH}`);
  }

  const rawReport = fs.readFileSync(REPORT_PATH, "utf8").replace(/^\uFEFF/, "");

  const report = JSON.parse(rawReport);

  if (!report.dryRun || !Array.isArray(report.results)) {
    throw new Error("Invalid report or report is not a dry run.");
  }

  if (report.totalFiles !== EXPECTED_FILES) {
    throw new Error(
      `Expected ${EXPECTED_FILES} PDFs, but dry-run report contains ${report.totalFiles}.`,
    );
  }

  console.log("==================================");
  console.log("ABSOLUTE DATA V2 COMPARISON");
  console.log("==================================");
  console.log("Expected PDFs:", EXPECTED_FILES);
  console.log("Dry-run results:", report.results.length);
  console.log("Connecting to MongoDB...");

  await mongoose.connect(MONGO_URI);

  const summary = {
    expectedFiles: EXPECTED_FILES,
    reportFiles: report.totalFiles,
    dryRunResults: report.results.length,
    originalRecordsFound: 0,
    exactMatches: 0,
    mismatches: 0,
    invalidDryRunResults: 0,
    missingOriginalRecords: 0,
    skippedResults: 0,
    duplicateSerialNumbers: 0,
    prizeGroupsChecked: 0,
    prizeGroupsMatched: 0,
    prizeGroupsMismatched: 0,
    totalMissingNumbers: 0,
    totalExtraNumbers: 0,
    comparisons: [],
  };

  const seenSerialNumbers = new Set();

  for (const parsed of report.results) {
    const serialNumber = String(parsed.serialNumber || "").trim();

    if (serialNumber && seenSerialNumbers.has(serialNumber)) {
      summary.duplicateSerialNumbers++;
    }

    if (serialNumber) {
      seenSerialNumbers.add(serialNumber);
    }

    if (parsed.status === "skipped") {
      summary.skippedResults++;
    }

    if (parsed.status !== "dry-run-valid" || parsed.valid !== true) {
      summary.invalidDryRunResults++;

      summary.comparisons.push({
        fileName: parsed.fileName,
        serialNumber,
        status: "DRY_RUN_NOT_VALID",
        reason: parsed.reason || parsed.validationErrors || null,
      });

      console.log(`INVALID: ${parsed.fileName}`);
      continue;
    }

    if (!serialNumber) {
      summary.missingOriginalRecords++;

      summary.comparisons.push({
        fileName: parsed.fileName,
        status: "MISSING_SERIAL_NUMBER",
      });

      continue;
    }

    const original = await AbsoluteData.findOne({
      serialNumber,
    }).lean();

    if (!original) {
      summary.missingOriginalRecords++;

      summary.comparisons.push({
        fileName: parsed.fileName,
        serialNumber,
        status: "ORIGINAL_RECORD_NOT_FOUND",
      });

      console.log(`NOT FOUND: ${serialNumber}`);
      continue;
    }

    summary.originalRecordsFound++;

    const differences = [];

    // --------------------------------------------------------
    // DATE COMPARISON
    // --------------------------------------------------------

    if (normalizeDate(parsed.date) !== normalizeDate(original.date)) {
      differences.push({
        type: "DATE_MISMATCH",
        expected: original.date,
        actual: parsed.date,
      });
    }

    // --------------------------------------------------------
    // PRIZE GROUP AND NUMBER COMPARISON
    // --------------------------------------------------------

    const originalGroups = groupByPrize(original.series);
    const parsedGroups = groupByPrize(parsed.series);

    const allPrizeAmounts = new Set([
      ...originalGroups.keys(),
      ...parsedGroups.keys(),
    ]);

    const prizeComparisons = [];

    for (const prize of [...allPrizeAmounts].sort((a, b) => b - a)) {
      summary.prizeGroupsChecked++;

      const expected = originalGroups.get(prize) || [];
      const actual = parsedGroups.get(prize) || [];

      const numberDifferences = findDifferences(expected, actual);

      const exactMatch =
        numberDifferences.missing.length === 0 &&
        numberDifferences.extra.length === 0;

      if (exactMatch) {
        summary.prizeGroupsMatched++;
      } else {
        summary.prizeGroupsMismatched++;
      }

      summary.totalMissingNumbers += numberDifferences.missing.length;
      summary.totalExtraNumbers += numberDifferences.extra.length;

      const prizeResult = {
        prize,
        originalCount: expected.length,
        parsedCount: actual.length,
        exactMatch,
        missingNumbers: numberDifferences.missing,
        extraNumbers: numberDifferences.extra,
      };

      prizeComparisons.push(prizeResult);

      if (!exactMatch) {
        differences.push({
          type: "PRIZE_NUMBERS_MISMATCH",
          ...prizeResult,
        });
      }
    }

    // --------------------------------------------------------
    // FINAL RESULT FOR THIS PDF
    // --------------------------------------------------------

    const exactMatch = differences.length === 0;

    if (exactMatch) {
      summary.exactMatches++;
    } else {
      summary.mismatches++;
    }

    summary.comparisons.push({
      fileName: parsed.fileName,
      serialNumber,
      date: parsed.date,
      status: exactMatch ? "EXACT_MATCH" : "MISMATCH",
      originalPrizeGroups: original.series.length,
      parsedPrizeGroups: parsed.series.length,
      prizeComparisons,
      differences,
    });

    console.log(`${exactMatch ? "MATCH" : "MISMATCH"}: ${serialNumber}`);
  }

  // ------------------------------------------------------------
  // FINAL VALIDATION
  // ------------------------------------------------------------

  const allFilesAccountedFor =
    summary.exactMatches +
      summary.mismatches +
      summary.invalidDryRunResults +
      summary.missingOriginalRecords ===
    EXPECTED_FILES;

  const passed =
    report.totalFiles === EXPECTED_FILES &&
    report.results.length === EXPECTED_FILES &&
    summary.exactMatches === EXPECTED_FILES &&
    summary.mismatches === 0 &&
    summary.invalidDryRunResults === 0 &&
    summary.missingOriginalRecords === 0 &&
    summary.skippedResults === 0 &&
    summary.duplicateSerialNumbers === 0 &&
    allFilesAccountedFor;

  const output = {
    generatedAt: new Date().toISOString(),
    sourceCollection: "absolute_data",
    targetCollection: "absolute_data_v2",
    dryRun: true,
    dryRunReport: REPORT_PATH,
    passed,
    summary,
  };

  fs.writeFileSync(OUTPUT_PATH, JSON.stringify(output, null, 2), "utf8");

  // ------------------------------------------------------------
  // CONSOLE SUMMARY
  // ------------------------------------------------------------

  console.log("\n==================================");
  console.log("100-PDF COMPARISON SUMMARY");
  console.log("==================================");

  console.log("Expected PDFs:", summary.expectedFiles);
  console.log("PDFs in report:", summary.reportFiles);
  console.log("Results checked:", summary.dryRunResults);
  console.log("Original records found:", summary.originalRecordsFound);

  console.log("----------------------------------");

  console.log("Exact matches:", summary.exactMatches);
  console.log("Mismatches:", summary.mismatches);
  console.log("Missing original records:", summary.missingOriginalRecords);
  console.log("Invalid dry runs:", summary.invalidDryRunResults);
  console.log("Skipped results:", summary.skippedResults);
  console.log("Duplicate serial numbers:", summary.duplicateSerialNumbers);

  console.log("----------------------------------");

  console.log("Prize groups checked:", summary.prizeGroupsChecked);
  console.log("Prize groups matched:", summary.prizeGroupsMatched);
  console.log("Prize groups mismatched:", summary.prizeGroupsMismatched);
  console.log("Missing numbers:", summary.totalMissingNumbers);
  console.log("Extra numbers:", summary.totalExtraNumbers);

  console.log("----------------------------------");

  console.log("FINAL RESULT:", passed ? "PASS" : "FAIL");

  console.log("\nReport saved to:");
  console.log(OUTPUT_PATH);

  await mongoose.disconnect();

  if (!passed) {
    process.exitCode = 1;
  }
}

main().catch(async (error) => {
  console.error("Comparison failed:", error);

  if (mongoose.connection.readyState !== 0) {
    await mongoose.disconnect();
  }

  process.exitCode = 1;
});
